/**
 * `orderGroups` against Python's answers — the shared ordered-groups cases.
 *
 * `docs/claude/ordered-groups-cases.json` is GENERATED by
 * `scistackplot/tests/test_ordered_groups_cases.py` from
 * `PlotSpec.ordered_groups`, which owns the rule; this module is its mirror
 * (the panel must show the order the figure will draw). A case here that fails
 * is the panel and the figure nesting differently. Never edit the JSON to make
 * this pass: change the rule in Python, regenerate, then fix `groups.ts`.
 *
 * `depths: null` is "no depths at all" (Python passes `None`); the TS
 * function takes `{}`, under which every factor is equally depthless.
 */

import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

import { orderGroups } from './groups.js'

interface OrderedGroupsCase {
  name: string
  roles: Record<string, string>
  declared: string[]
  depths: Record<string, number | null> | null
  expected: string[]
}

/** Walks up from this file: `npm test` runs the compiled copy in `dist/test`,
 * at a different depth than the source. */
function casesFile(): string {
  let dir = dirname(fileURLToPath(import.meta.url))
  for (let up = 0; up < 10; up++) {
    const candidate = join(dir, 'docs', 'claude', 'ordered-groups-cases.json')
    try {
      readFileSync(candidate)
      return candidate
    } catch {
      dir = dirname(dir)
    }
  }
  throw new Error(
    'docs/claude/ordered-groups-cases.json not found by walking up from ' +
      fileURLToPath(import.meta.url)
  )
}

const cases: OrderedGroupsCase[] = JSON.parse(readFileSync(casesFile(), 'utf8')).cases

test('the shared file has cases', () => {
  assert.ok(cases.length > 0)
})

for (const c of cases) {
  test(`ordered groups: ${c.name}`, () => {
    const holders = Object.entries(c.roles)
      .filter(([, role]) => role === 'group')
      .map(([name]) => name)
    assert.deepEqual(orderGroups(c.declared, holders, c.depths ?? {}), c.expected)
  })
}
